package com.example.yuejie;
import android.app.*;import android.content.*;import android.database.sqlite.*;import android.os.*;import org.json.*;import java.io.*;import java.util.*;
/** Restore only user reading state from the pre-test snapshot; retain fresh catalog/cache data. */
public final class RestoreTurnState extends Instrumentation {
 public void onCreate(Bundle args){start();}
 ContentValues values(JSONObject row)throws Exception{ContentValues v=new ContentValues();for(Iterator<String> it=row.keys();it.hasNext();){String k=it.next();Object x=row.get(k);if(x==JSONObject.NULL)v.putNull(k);else if(x instanceof Number)v.put(k,((Number)x).longValue());else v.put(k,x.toString());}return v;}
 public void onStart(){Bundle result=new Bundle();try{JSONObject saved;try(InputStream in=new FileInputStream(new File(getTargetContext().getFilesDir(),"turn-state-before.json"))){saved=new JSONObject(new String(ProtocolCrypto.read(in),"UTF-8"));}LocalLibrary library=new LocalLibrary(getTargetContext());SQLiteDatabase db=library.getWritableDatabase();db.beginTransaction();try{for(String table:new String[]{"progress","bookmarks"}){db.delete(table,null,null);JSONArray rows=saved.getJSONArray(table);for(int i=0;i<rows.length();i++)db.insertOrThrow(table,null,values(rows.getJSONObject(i)));}JSONArray books=saved.getJSONArray("books");for(int i=0;i<books.length();i++){JSONObject book=books.getJSONObject(i);ContentValues v=new ContentValues();v.put("last_read",book.getLong("last_read"));v.put("added",book.getLong("added"));db.update("books",v,"id=?",new String[]{book.getString("id")});}db.setTransactionSuccessful();}finally{db.endTransaction();}SharedPreferences.Editor prefs=getTargetContext().getSharedPreferences("ReaderActivity",0).edit().clear();JSONObject p=saved.getJSONObject("preferences");for(Iterator<String> it=p.keys();it.hasNext();){String k=it.next();JSONObject entry=p.getJSONObject(k);switch(entry.getString("type")){case "boolean":prefs.putBoolean(k,entry.getBoolean("value"));break;case "int":prefs.putInt(k,entry.getInt("value"));break;case "long":prefs.putLong(k,entry.getLong("value"));break;case "float":prefs.putFloat(k,(float)entry.getDouble("value"));break;default:prefs.putString(k,entry.getString("value"));}}prefs.commit();library.close();result.putString("stream","PASS original reading settings, positions, books and bookmarks restored");finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
